window.showPreviewInfo=function(title){document.querySelector('#preview-title').textContent=title;document.querySelector('#preview-dialog').showModal();};
document.addEventListener('click',function(e){const a=e.target.closest('a');if(!a||a.target==='_blank'||a.closest('.preview-banner')||a.dataset.vxFilter)return;const href=a.getAttribute('href')||'';if(href==='/'||href==='/m'){e.preventDefault();location.href=href==='/m'?'/?layout=mobile':'/';return;}if(href==='#vx-dashboard'||href==='#vx-ranking')return;e.preventDefault();const label=a.textContent.trim();if(href.includes('#v6-stock')){document.querySelector('#vx-ranking').scrollIntoView();return;}if(href.includes('#v6-market')){document.querySelector('#vx-indices').scrollIntoView();return;}window.showPreviewInfo(label);});
